"use client";

import { runs, relativeTime, type Run } from "@/lib/mock-data";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

const statusVariant: Record<Run["status"], "success" | "error" | "info" | "warning"> = {
  success: "success",
  failed: "error",
  running: "info",
  killed: "warning",
};

const statusLabel: Record<Run["status"], string> = {
  success: "Completed",
  failed: "Failed",
  running: "Running",
  killed: "Killed",
};

function RunCard({ run }: { run: Run }) {
  return (
    <div className="group rounded-xl bg-surface p-5 shadow-[var(--shadow-card)] transition-all duration-200 hover:shadow-[var(--shadow-elevated)]">
      {/* Top row: job name + badge */}
      <div className="flex items-start justify-between gap-2 mb-3">
        <p className="text-sm font-medium text-text-primary truncate">
          {run.jobName}
        </p>
        <Badge variant={statusVariant[run.status]} className="flex-shrink-0">
          {statusLabel[run.status]}
        </Badge>
      </div>

      {/* Details grid */}
      <div className="grid grid-cols-2 gap-x-4 gap-y-1.5 text-[11px]">
        <div>
          <span className="text-text-secondary/60">Started</span>
          <p className="text-text-secondary font-mono">{relativeTime(run.started)}</p>
        </div>
        <div>
          <span className="text-text-secondary/60">Duration</span>
          <p className="text-text-primary font-mono">{run.duration}</p>
        </div>
        <div>
          <span className="text-text-secondary/60">Exit Code</span>
          <p
            className={cn(
              "font-mono",
              run.exitCode === 0
                ? "text-success"
                : run.exitCode === null
                  ? "text-info"
                  : "text-error"
            )}
          >
            {run.exitCode === null ? "--" : run.exitCode}
          </p>
        </div>
        <div>
          <span className="text-text-secondary/60">Cost</span>
          <p className="text-text-primary font-mono">{run.cost}</p>
        </div>
      </div>
    </div>
  );
}

export function RecentRuns() {
  // Show the 12 most recent runs (already sorted newest-first in mock data)
  const recentRuns = runs.slice(0, 12);

  return (
    <section>
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-base font-semibold text-text-primary">
          Recent Runs
        </h2>
        <button className="text-xs text-text-secondary hover:text-primary transition-colors cursor-pointer font-medium">
          System Logs
        </button>
      </div>

      {/* Card grid */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4">
        {recentRuns.map((run) => (
          <RunCard key={run.id} run={run} />
        ))}
      </div>
    </section>
  );
}
