"use client";

import { cn } from "@/lib/utils";

interface PillToggleProps {
  value: string;
  onChange: (value: string) => void;
  options: { label: string; value: string }[];
}

export function PillToggle({ value, onChange, options }: PillToggleProps) {
  return (
    <div className="inline-flex items-center gap-1 rounded-full bg-surface-elevated/60 p-1">
      {options.map((option) => (
        <button
          key={option.value}
          onClick={() => onChange(option.value)}
          className={cn(
            "px-5 py-1.5 rounded-full text-sm font-medium transition-all duration-200 cursor-pointer",
            value === option.value
              ? "bg-primary text-bg"
              : "text-text-secondary hover:text-text-primary"
          )}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}
