"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { topCostJobs, dailyCostTrend, nextScheduledRun } from "@/lib/mock-data";
import { cn } from "@/lib/utils";
import { ClockIcon } from "@heroicons/react/20/solid";

const SLIDE_INTERVAL = 5000;

/* ── Donut Chart ─────────────────────────────────────────────────────────── */
function DonutChart() {
  const total = topCostJobs.reduce((s, j) => s + j.cost, 0);
  const radius = 52;
  const circumference = 2 * Math.PI * radius;
  let offset = 0;

  return (
    <div className="flex items-center gap-6">
      <div className="relative flex-shrink-0">
        <svg width="130" height="130" viewBox="0 0 130 130">
          {topCostJobs.map((job) => {
            const pct = job.cost / total;
            const dashLen = pct * circumference;
            const dashOffset = -offset;
            offset += dashLen;
            return (
              <circle
                key={job.name}
                cx="65"
                cy="65"
                r={radius}
                fill="none"
                stroke={job.color}
                strokeWidth="16"
                strokeDasharray={`${dashLen} ${circumference - dashLen}`}
                strokeDashoffset={dashOffset}
                transform="rotate(-90 65 65)"
              />
            );
          })}
          <text
            x="65"
            y="62"
            textAnchor="middle"
            className="fill-text-primary font-semibold"
            style={{ fontSize: "16px" }}
          >
            ${total.toFixed(2)}
          </text>
          <text
            x="65"
            y="78"
            textAnchor="middle"
            className="fill-text-secondary"
            style={{ fontSize: "10px" }}
          >
            total
          </text>
        </svg>
      </div>
      <div className="flex flex-col gap-1.5">
        {topCostJobs.map((job) => (
          <div key={job.name} className="flex items-center gap-2">
            <span
              className="h-2.5 w-2.5 rounded-full flex-shrink-0"
              style={{ backgroundColor: job.color }}
            />
            <span className="text-[11px] text-text-secondary font-mono">
              {job.name}
            </span>
            <span className="text-[11px] text-text-primary font-medium ml-auto pl-3">
              ${job.cost.toFixed(2)}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ── Bar Chart ───────────────────────────────────────────────────────────── */
function BarChart() {
  const max = Math.max(...dailyCostTrend.map((d) => d.cost));

  return (
    <div className="flex items-end gap-2.5 h-32">
      {dailyCostTrend.map((d) => (
        <div key={d.day} className="flex flex-1 flex-col items-center gap-1">
          <span className="text-[10px] text-text-secondary font-mono">
            ${d.cost.toFixed(2)}
          </span>
          <div className="w-full relative flex-1 flex items-end">
            <div
              className="w-full rounded-t-sm"
              style={{
                height: `${(d.cost / max) * 100}%`,
                background:
                  d.cost === max
                    ? "var(--primary)"
                    : "color-mix(in oklch, var(--primary), transparent 60%)",
              }}
            />
          </div>
          <span className="text-[10px] text-text-secondary">{d.day}</span>
        </div>
      ))}
    </div>
  );
}

/* ── Next Run Timer ──────────────────────────────────────────────────────── */
function NextRunTimer() {
  return (
    <div className="flex flex-col items-center justify-center h-full gap-4 py-4">
      <ClockIcon className="h-8 w-8 text-primary/60" />
      <div className="text-center">
        <p className="text-xs font-medium text-text-secondary uppercase tracking-wider mb-2">
          Next Scheduled Run
        </p>
        <p className="text-sm font-semibold text-text-primary mb-1">
          {nextScheduledRun.jobName}
        </p>
        <p className="text-3xl font-semibold text-primary tabular-nums tracking-tight">
          {nextScheduledRun.countdown}
        </p>
        <p className="text-[11px] text-text-secondary font-mono mt-1">
          {nextScheduledRun.schedule}
        </p>
      </div>
    </div>
  );
}

/* ── Carousel ────────────────────────────────────────────────────────────── */
const slides = [
  { id: "cost", title: "Top Cost Jobs", content: <DonutChart /> },
  { id: "trend", title: "Daily Cost Trend", content: <BarChart /> },
  { id: "next", title: "Next Run", content: <NextRunTimer /> },
];

export function WidgetCarousel() {
  const [active, setActive] = useState(0);
  const [paused, setPaused] = useState(false);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const advance = useCallback(() => {
    setActive((prev) => (prev + 1) % slides.length);
  }, []);

  useEffect(() => {
    if (paused) {
      if (intervalRef.current) clearInterval(intervalRef.current);
      return;
    }
    intervalRef.current = setInterval(advance, SLIDE_INTERVAL);
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [paused, advance]);

  return (
    <div
      className="rounded-lg border border-border bg-surface overflow-hidden flex flex-col h-full"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-5 pt-4 pb-2">
        <h3 className="text-sm font-medium text-text-secondary">
          {slides[active].title}
        </h3>
      </div>

      {/* Slide area */}
      <div className="flex-1 px-5 pb-3 relative overflow-hidden">
        {slides.map((slide, i) => (
          <div
            key={slide.id}
            className={cn(
              "absolute inset-0 px-5 pb-3 flex items-center transition-all duration-500 ease-in-out",
              i === active
                ? "opacity-100 translate-x-0"
                : i < active
                  ? "opacity-0 -translate-x-8"
                  : "opacity-0 translate-x-8"
            )}
          >
            {slide.content}
          </div>
        ))}
      </div>

      {/* Dot indicators */}
      <div className="flex items-center justify-center gap-1.5 pb-4">
        {slides.map((slide, i) => (
          <button
            key={slide.id}
            onClick={() => setActive(i)}
            className={cn(
              "h-1.5 rounded-full transition-all duration-300 cursor-pointer",
              i === active
                ? "w-5 bg-primary"
                : "w-1.5 bg-text-secondary/30 hover:bg-text-secondary/50"
            )}
            aria-label={`Go to ${slide.title}`}
          />
        ))}
      </div>
    </div>
  );
}
